EVENTS = [
    dict(id="genevieve-attila-451", title="Geneviève holds Paris against panic", periodId="lutetia-200", date="451", kind="civic",
         at=dict(latlon=(48.8547, 2.3478)), effect="crowd",
         text="As Attila's Huns swept into Gaul, the people of Paris, as Lutetia was now called, prepared to flee. A young consecrated woman, Geneviève, gathered the women to pray and told the men to stay. Attila turned south to Orléans instead. Her Life, written about 520, makes her the city's protector; her relics would be carried through the streets in every later crisis.",
         sourceIds=["vita-genovefae", "wiki-genevieve"]),
    dict(id="julian-360", title="Julian proclaimed emperor at Lutetia", periodId="lutetia-200", date="February–March 360", kind="ceremony",
         at=dict(latlon=(48.8562, 2.3445)), effect="crowd",
         text="The Caesar Julian had wintered at Lutetia, 'my dear Lutetia', between campaigns on the Rhine. When Constantius II ordered his best troops east, the soldiers surrounded his palace at night and hailed him Augustus, raising him on an infantry shield. Ammianus says he resisted, then accepted. Julian later described the island town, its clear river and the vines and figs that Parisians wrapped in straw for winter.",
         sourceIds=["ammianus", "julian-misopogon", "wiki-julian"]),
    dict(id="viking-siege-885", title="The Vikings besiege Paris", periodId="capetian-1000", date="November 885 – October 886", kind="disaster",
         at=dict(landmarkId="grand-chatelet"), effect="fire",
         text="A Danish fleet of hundreds of ships, by the monk Abbo's count, demanded passage up the Seine. Count Odo and Bishop Gozlin refused. They attacked the half-built tower at the Grand Pont's head with rams and fire. In February a flood swept away the Petit Pont and its tower fell, its twelve defenders killed. The emperor Charles the Fat paid them and let them go on to plunder Burgundy; in 888 Odo was made king.",
         sourceIds=["abbo", "wiki-siege-885"]),
    dict(id="expulsion-1182", title="Philippe Auguste expels the Jews", periodId="capetian-1000", date="April 1182", kind="civic",
         at=dict(spotId="synagogue"), effect="none",
         text="The young king ordered the Jews of the royal domain to leave within three months, cancelled debts owed to them and seized their houses. The synagogue of the Cité was given to the Church, probably becoming the church of Sainte-Madeleine; houses went to the drapers and furriers. The king's chronicler Rigord presents it as piety; it was also a windfall for the treasury. Jews were let back in 1198.",
         sourceIds=["rigord", "wiki-jews-france"]),
    dict(id="notre-dame-1163", title="The first stone of Notre-Dame", periodId="capetian-1000", date="1163", kind="construction",
         at=dict(landmarkId="notre-dame"), effect="construction",
         text="Bishop Maurice de Sully, son of a peasant, began a new cathedral east of the old Saint-Étienne, to be the largest of its day. Tradition says Pope Alexander III, in exile in France, laid the first stone. A new street, the rue Neuve-Notre-Dame, was cut to bring the stone from the quays. The high altar of the new choir was consecrated in 1182.",
         sourceIds=["wiki-notre-dame", "erlande"]),
    dict(id="wall-1190", title="Philippe Auguste walls the right bank", periodId="philippe-1250", date="1190", kind="construction",
         at=dict(landmarkId="philippe-wall"), effect="construction",
         text="Before leaving on the Third Crusade, the king ordered the burghers to enclose the right bank with a stone wall; they finished it about 1209, and the king paid for the left-bank half. It took in fields and vineyards as well as houses, and within a century they had filled up. Rigord praises the king for it; its towers and gates fixed the shape of Paris for 150 years.",
         sourceIds=["rigord", "wiki-wall-philippe"]),
    dict(id="strike-1229", title="The University goes on strike", periodId="philippe-1250", date="March 1229", kind="riot",
         at=dict(spotId="rue-du-fouarre"), effect="crowd",
         text="A carnival brawl over a tavern bill in the faubourg Saint-Marcel ended with the queen regent's sergeants killing several students. When no redress came, the masters suspended teaching and left Paris for Orléans, Angers, Toulouse, Oxford and Cambridge. Two years later Pope Gregory IX's bull Parens scientiarum (1231) confirmed the University's right to strike and its independence.",
         sourceIds=["matthew-paris", "wiki-strike-1229", "rashdall"]),
    dict(id="crown-of-thorns-1239", title="Louis IX brings the Crown of Thorns", periodId="philippe-1250", date="August 1239", kind="procession",
         at=dict(landmarkId="notre-dame"), effect="procession",
         text="Louis IX bought the relic from the bankrupt Latin emperor of Constantinople, who had pawned it to Venetian bankers. The king and his brother Robert, barefoot and in plain tunics, carried it into Paris and to Notre-Dame, then to the palace chapel. The Sainte-Chapelle was built to house it; its glass tells the story of this procession.",
         sourceIds=["wiki-crown-of-thorns", "cohen-sainte-chapelle"]),
    dict(id="sainte-chapelle-1248", title="The Sainte-Chapelle consecrated", periodId="philippe-1250", date="26 April 1248", kind="ceremony",
         at=dict(landmarkId="sainte-chapelle"), effect="procession",
         text="Six years after it was begun, the palace chapel was consecrated in two ceremonies: the upper chapel by the papal legate Eudes de Châteauroux, the lower by the archbishop of Bourges. Two months later Louis IX left on crusade. The relics cost about 135,000 livres, the chapel about 40,000: the reliquary cost less than what it held.",
         sourceIds=["wiki-sainte-chapelle", "cohen-sainte-chapelle"]),
    dict(id="etienne-marcel-1358", title="Étienne Marcel storms the palace", periodId="valois-1550", date="22 February 1358", kind="riot",
         at=dict(landmarkId="palais-cite"), effect="crowd",
         text="With King John a prisoner in England, the provost of the merchants led some 3,000 armed Parisians into the palace and had the marshals of Champagne and Normandy cut down in front of the dauphin Charles, whose robe was splashed with their blood. Marcel put his own red-and-blue hood on the prince's head. In July Marcel was killed at the Porte Saint-Antoine; the dauphin never forgot.",
         sourceIds=["wiki-etienne-marcel", "jones-paris"]),
    dict(id="bastille-begun-1370", title="The first stone of the Bastille", periodId="valois-1550", date="22 April 1370", kind="construction",
         at=dict(landmarkId="bastille"), effect="construction",
         text="Hugues Aubriot, Charles V's provost of Paris, laid the first stone of a bastide to guard the Porte Saint-Antoine and the king's new residence, the Hôtel Saint-Pol. Finished about 1383, its eight towers became the anchor of the new right-bank wall. Aubriot, the story goes, was later among its first prisoners.",
         sourceIds=["wiki-bastille", "lusebrink"]),
    dict(id="pont-notre-dame-1499", title="The Pont Notre-Dame falls into the Seine", periodId="valois-1550", date="25 October 1499", kind="disaster",
         at=dict(landmarkId="pont-notre-dame"), effect="crowd",
         text="The timber bridge of 1413, carrying some sixty houses, had been neglected by the city. On the morning of 25 October its piles gave way and the whole bridge, houses and all, collapsed into the river. Warned by carpenters, most people had fled. The provost and échevins were jailed for negligence, and the city rebuilt the bridge in stone.",
         sourceIds=["wiki-pont-notre-dame", "jones-paris"]),
    dict(id="st-bartholomew-1572", title="The St Bartholomew's Day massacre", periodId="valois-1550", date="24 August 1572", kind="riot",
         at=dict(landmarkId="louvre"), effect="fire",
         text="Six days after the Protestant Henri of Navarre married the king's sister, the royal council decided to strike the Huguenot leaders gathered for the wedding. At dawn Admiral Coligny was killed near the Louvre and his body thrown from a window; Protestant gentlemen were cut down in the Louvre's court. Parisian militias spread the killing through the city for days; perhaps 2,000 to 3,000 died in Paris.",
         sourceIds=["wiki-st-bartholomew", "diefendorf"]),
    dict(id="henri-iv-1610", title="Henri IV assassinated", periodId="valois-1550", date="14 May 1610", kind="civic",
         at=dict(landmarkId="innocents"), effect="crowd",
         text="The king's coach, on its way to the Arsenal, was stopped in the narrow rue de la Ferronnerie, beside the wall of the Innocents, by a cart of hay and a cart of wine. François Ravaillac, a Catholic zealot, climbed on the wheel and stabbed him twice. The king died within minutes. Ravaillac was torn apart by horses on the Place de Grève.",
         sourceIds=["wiki-ravaillac", "lestoile"]),
    dict(id="bastille-1789", title="The storming of the Bastille", periodId="louis-1789", date="14 July 1789", kind="riot",
         at=dict(landmarkId="bastille"), effect="fire",
         text="Looking for gunpowder after taking muskets at the Invalides, a crowd of artisans of the faubourg Saint-Antoine, guards and townsmen besieged the fortress. After hours of firing and the arrival of mutinous gardes françaises with cannon, the governor de Launay surrendered at about five. Some 98 attackers died. De Launay was killed on the way to the Hôtel de Ville; seven prisoners were freed.",
         sourceIds=["wiki-storming-bastille", "schama", "lusebrink"]),
    dict(id="innocents-closed-1780", title="The Cemetery of the Innocents is closed", periodId="louis-1789", date="1780; exhumed 1785–1787", kind="civic",
         at=dict(landmarkId="innocents"), effect="procession",
         text="After a cellar wall in the rue de la Lingerie gave way under the weight of a mass grave, the cemetery was closed in 1780. From 1785 the bones of perhaps two million dead were dug up and carried by night, in black-draped carts followed by priests chanting, to the old quarries south of the city: the Catacombs.",
         sourceIds=["wiki-innocents", "aries", "mercier"]),
]

